<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Repositories;
use PDO; use PHPUnit\Framework\TestCase; use Sentinel\Core\Config; use Sentinel\Core\Database; use Sentinel\Core\RuntimeContext; use Sentinel\Repositories\DeviceAssignmentRepository;
final class DeviceAssignmentRepositoryTest extends TestCase { public function testAssignmentsHideForeignDevices():void{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));$db->execute('CREATE TABLE device_assignments (device_assignment_id INTEGER,company_id INTEGER,device_id INTEGER,employee_id INTEGER,employee_assignment_id INTEGER,starts_at TEXT,ends_at TEXT,assignment_status TEXT,assigned_by_user_id INTEGER,returned_at TEXT,notes TEXT,created_at TEXT,updated_at TEXT)');$db->execute("INSERT INTO device_assignments VALUES (1,101,1,7,NULL,'2026-01-01',NULL,'ACTIVE',NULL,NULL,NULL,NULL,NULL),(2,202,2,8,NULL,'2026-01-01',NULL,'ACTIVE',NULL,NULL,NULL,NULL,NULL)");$context=new RuntimeContext();$context->setTenantId(101);$repository=new DeviceAssignmentRepository($db,$context);self::assertCount(1,$repository->listForDevice('1'));self::assertNull($repository->findByIdForCompany('2'));} }